select t.refund_order_id refundOrderId,t.fee_name feeName,t.detail_id detailId,t.start_time
startTime,t.remark,t.status_cd statusCd,t.end_time endTime,t.received_amount receivedAmount,t.community_id
communityId,t.rfd_id rfdId,t.fee_id feeId,t.create_time createTime
from refund_fee_detail t
where 1 =1

    and t.refund_order_id= #{refundOrderId}


    and t.refund_order_id in

        #{item}



    and t.fee_name= #{feeName}


    and t.detail_id= #{detailId}


    and t.start_time= #{startTime}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.end_time= #{endTime}


    and t.received_amount= #{receivedAmount}


    and t.community_id= #{communityId}


    and t.rfd_id= #{rfdId}


    and t.fee_id= #{feeId}

order by t.create_time desc

    limit #{page}, #{row}

